fn main() {
    let mut tries = 0;
    let result = loop {
        tries += 1;
        if tries == 3 {
            break tries * 10;
        }
    };
    println!("Stopped after {tries} tries, result {result}");
}

fn main() {
    let mut n = 3;
    while n > 0 {
        println!("{n}");
        n -= 1;
    }

    for i in 0..3 {
        println!("i = {i}");
    }

    let fruits = ["apple", "pear", "plum"];
    for fruit in fruits {
        println!("I like {fruit}");
    }
}

